function buildTopicFilters(){
  const bar=document.getElementById('filter-bar');
  const sep=bar.querySelector('.filter-sep');
  const statsEl=bar.querySelector('.archive-stats');
  const topics=[...new Set(ARTICLES.map(a=>a.topic))].sort();
  topics.forEach(t=>{
    const btn=document.createElement('button');
    btn.className='filter-btn';btn.textContent=t;
    btn.style.setProperty('--tc',TOPIC_COLORS[t]||'#6b7280');
    btn.onclick=function(){setFilter('topic:'+t,this);};
    bar.insertBefore(btn,statsEl);
  });
}

function setFilter(f,btn){
  currentFilter=f;
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
  renderArchive();
  renderBookView();
  renderTimelineView();
}

function filterArticles(){
  currentSearch=document.getElementById('search-input').value.toLowerCase();
  renderArchive();
  renderBookView();
  renderTimelineView();
}

function getFilteredArticles(){
  return ARTICLES.filter(a=>{
    const searchBlob=[a.title,a.summary,a.author,a.topic].filter(Boolean).join(' ').toLowerCase();
    const matchesSearch=!currentSearch||searchBlob.includes(currentSearch);
    const matchesFilter=currentFilter==='all'
      ||(currentFilter.startsWith('author:')&&a.author===currentFilter.slice(7))
      ||(currentFilter.startsWith('topic:')&&a.topic===currentFilter.slice(6));
    return matchesSearch&&matchesFilter;
  });
}

