function getGraphDegrees(graph=buildSemanticGraph()){
  const degrees=new Map(ARTICLES.map(a=>[a.id,0]));
  graph.edges.forEach(({source,target})=>{
    degrees.set(source,(degrees.get(source)||0)+1);
    degrees.set(target,(degrees.get(target)||0)+1);
  });
  return degrees;
}
function escAttr(s){if(!s)return'';return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/'/g,'&#39;');}
document.getElementById('reader-modal').addEventListener('click',function(e){if(e.target===this)closeReader();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeReader();});
